	rawSchemaJobv0alpha1             = []byte(`{"DeleteJobOptions":{"additionalProperties":false,"properties":{"paths":{"description":"Paths to be deleted. Examples:\n- dashboard.json (for a file)\n- a/b/c/other-dashboard.json (for a file)\n- nested/deep/ (for a directory)","items":{"type":"string"},"type":"array"},"ref":{"description":"Ref to the branch or commit hash to delete from","type":"string"},"resources":{"description":"Resources to delete\nThis option has been created because currently the frontend does not use\nstandarized app platform APIs. For performance and API consistency reasons, the preferred option\nis it to use the paths.","items":{"$ref":"#/components/schemas/ResourceRef"},"type":"array"}},"type":"object"},"ExportJobOptions":{"additionalProperties":false,"properties":{"branch":{"description":"Target branch for export (only git)","type":"string"},"folder":{"description":"The source folder (or empty) to export","type":"string"},"generateNewFolderIDs":{"description":"GenerateNewFolderIDs writes a freshly generated identifier into each\nexported folder's metadata (_folder.json) instead of preserving the\nexisting folder UID. Use this to produce a portable export that creates\nnew folders on a subsequent sync rather than taking over the originals.\nHas no effect when folder metadata is not written.","type":"boolean"},"message":{"description":"Message to use when committing the changes in a single commit.\nDeprecated: set JobSpec.Message instead. This field is kept for\nbackwards compatibility and is only used when JobSpec.Message is empty.","type":"string"},"path":{"description":"Prefix in target file system","type":"string"},"resources":{"description":"Resources to export. When empty, every unmanaged resource in the namespace\nis exported (legacy behavior). When non-empty, only the listed resources\nare exported — the folder hierarchy is still emitted so parent paths resolve.\nCurrently only unmanaged Dashboards are supported.","items":{"$ref":"#/components/schemas/ResourceRef"},"type":"array"}},"type":"object"},"FixFolderMetadataJobOptions":{"additionalProperties":false,"properties":{"ref":{"description":"Ref to the branch to create the commit on (uses repository's default branch if not specified)","type":"string"}},"type":"object"},"Job":{"properties":{"spec":{"$ref":"#/components/schemas/spec"},"status":{"$ref":"#/components/schemas/status"}},"required":["spec"]},"JobResourceSummary":{"additionalProperties":false,"properties":{"create":{"type":"integer"},"delete":{"type":"integer"},"error":{"type":"integer"},"errors":{"description":"Report errors/warnings for this resource type\nThis may not be an exhaustive list and recommend looking at the logs for more info","items":{"type":"string"},"type":"array"},"group":{"type":"string"},"kind":{"type":"string"},"noop":{"description":"No action required (useful for sync)","type":"integer"},"total":{"type":"integer"},"totalChanges":{"description":"TotalChanges is the action-aware count of resources changed for this group/kind,\nset by the progress recorder as results are recorded. Used for the job-duration\nhistogram's resources_changed bucket.","type":"integer"},"update":{"type":"integer"},"warning":{"type":"integer"},"warnings":{"items":{"type":"string"},"type":"array"},"write":{"type":"integer"}},"type":"object"},"MigrateJobOptions":{"additionalProperties":false,"properties":{"branch":{"description":"Target branch for the migration (git only). When set to a branch other\nthan the repository's configured branch, the migration writes the exported\nresources to that branch (a pull request workflow) and removes the migrated\nresources from the instance instead of taking ownership of them — they\nreturn as managed resources once the branch is merged and a regular sync\nruns on the configured branch. When empty (or equal to the configured\nbranch), the migration writes directly to the configured branch and takes\nownership of the exported resources.","type":"string"},"generateNewFolderIDs":{"description":"GenerateNewFolderIDs writes a freshly generated identifier into each\nexported folder's metadata (_folder.json) instead of preserving the\nexisting folder UID. The subsequent pull creates new folders rather than\ntaking over the originals. Has no effect when folder metadata is not written.","type":"boolean"},"message":{"description":"Message to use when committing the changes in a single commit.\nDeprecated: set JobSpec.Message instead. This field is kept for\nbackwards compatibility and is only used when JobSpec.Message is empty.","type":"string"},"resources":{"description":"Resources to migrate. When empty, every unmanaged resource in the namespace\nis migrated (legacy behavior). When non-empty, only the listed resources\nare exported to the repository — the folder hierarchy is still emitted so\nparent paths resolve, and the subsequent pull phase only takes ownership\nof those resources.\nCurrently only unmanaged Dashboards are supported.","items":{"$ref":"#/components/schemas/ResourceRef"},"type":"array"},"skipResourceDeletion":{"description":"SkipResourceDeletion keeps the migrated resources on the instance instead of\nremoving them. By default a migration deletes the resources it moved (the\nwhole namespace for an instance target, or the exported resources for a\nbranch migration); when true, no deletion happens and the resources are\nleft in place.","type":"boolean"}},"type":"object"},"MoveJobOptions":{"additionalProperties":false,"properties":{"paths":{"description":"Paths to be deleted. Examples:\n- dashboard.json (for a file)\n- a/b/c/other-dashboard.json (for a file)\n- nested/deep/ (for a directory)","items":{"type":"string"},"type":"array"},"ref":{"description":"Ref to the branch or commit hash that should move","type":"string"},"resources":{"description":"Resources to move\nThis option has been created because currently the frontend does not use\nstandarized app platform APIs. For performance and API consistency reasons, the preferred option\nis it to use the paths.","items":{"$ref":"#/components/schemas/ResourceRef"},"type":"array"},"targetPath":{"description":"Destination path for the move (e.g. \"new-location/\")","type":"string"}},"type":"object"},"PullRequestJobOptions":{"additionalProperties":false,"properties":{"forkURL":{"description":"URL of the head repository for a pull request from a fork, when available.","type":"string"},"hash":{"description":"The specific commit hash that triggered this notice","type":"string"},"isFork":{"description":"Whether the pull request's head repository differs from its base repository.\nOmitted when repository identities were unavailable, including older jobs.","type":"boolean"},"pr":{"description":"Pull request number (when appropriate)","type":"integer"},"ref":{"description":"The branch of commit hash","type":"string"},"url":{"description":"URL to the originator (eg, PR URL)","type":"string"}},"type":"object"},"RepositoryURLs":{"additionalProperties":false,"properties":{"compareURL":{"description":"Compare this version to the target branch","type":"string"},"newPullRequestURL":{"description":"A URL that will create a new pull request for this branch","type":"string"},"repositoryURL":{"description":"A URL pointing to the repository this lives in","type":"string"},"sourceURL":{"description":"A URL pointing to the file or ref in the repository","type":"string"}},"type":"object"},"ResourceRef":{"additionalProperties":false,"properties":{"group":{"description":"Group is the group of the resource, such as \"dashboard.grafana.app\".","type":"string"},"kind":{"description":"Kind is the type of resource, for example, \"Dashboard\".","type":"string"},"name":{"description":"Name is the name of the resource, such as a dashboard UID.","type":"string"}},"type":"object"},"SyncJobOptions":{"additionalProperties":false,"properties":{"incremental":{"description":"Incremental synchronization for versioned repositories","type":"boolean"}},"required":["incremental"],"type":"object"},"TestJobOptions":{"additionalProperties":false,"description":"TestJobOptions configures a synthetic performance-testing job. The job does\nno real work; it sleeps for Duration and then completes. It is only usable\nwhen the provisioning.performance feature flag is enabled.","properties":{"duration":{"description":"Duration is how long the job should sleep before completing, expressed as\na Go duration string (for example \"10s\" or \"2m\"). It must be positive and\nis capped by the server to keep a single job's runtime predictable.","type":"string"},"progressUpdates":{"description":"ProgressUpdates controls how many progress notifications the job emits\nwhile running. A value of 0 uses the server default.","type":"integer"}},"type":"object"},"spec":{"additionalProperties":false,"properties":{"action":{"enum":["pull","push","pr","migrate","delete","move","fixFolderMetadata","releaseResources","deleteResources","test"],"type":"string"},"delete":{"$ref":"#/components/schemas/DeleteJobOptions","description":"Delete when the action is ` + "`" + `delete` + "`" + `"},"fixFolderMetadata":{"$ref":"#/components/schemas/FixFolderMetadataJobOptions","description":"Options when the action is ` + "`" + `fix-folder-metadata` + "`" + `"},"message":{"description":"Commit message for this job. Applies to job actions that produce\ncommits (delete, move, migrate, push, fixFolderMetadata).\nWhen empty, the backend falls back to the action-specific message\nfield (ExportJobOptions.Message, MigrateJobOptions.Message) for\nbackwards compatibility, then to a built-in default.","type":"string"},"migrate":{"$ref":"#/components/schemas/MigrateJobOptions","description":"Required when the action is ` + "`" + `migrate` + "`" + `"},"move":{"$ref":"#/components/schemas/MoveJobOptions","description":"Move when the action is ` + "`" + `move` + "`" + `"},"pr":{"$ref":"#/components/schemas/PullRequestJobOptions","description":"Pull request options"},"pull":{"$ref":"#/components/schemas/SyncJobOptions","description":"Required when the action is ` + "`" + `pull` + "`" + `"},"push":{"$ref":"#/components/schemas/ExportJobOptions","description":"Required when the action is ` + "`" + `push` + "`" + `"},"repository":{"description":"The the repository reference (for now also in labels)\nThis value is required, but will be popuplated from the job making the request","type":"string"},"test":{"$ref":"#/components/schemas/TestJobOptions","description":"Required when the action is ` + "`" + `test` + "`" + `"}},"required":["action"],"type":"object"},"status":{"additionalProperties":false,"properties":{"errors":{"items":{"type":"string"},"type":"array"},"finished":{"type":"integer"},"message":{"type":"string"},"progress":{"description":"Optional value 0-100 that can be set while running","type":"number"},"progressUpdates":{"description":"ProgressUpdates is the number of times the job's status has been written\nwhile it was processed. It is carried over to the historic job so the total\nnumber of progress updates a job went through remains observable after\ncompletion.","type":"integer"},"started":{"type":"integer"},"state":{"enum":["pending","working","success","error","warning"],"type":"string"},"summary":{"description":"Summary of processed actions","items":{"$ref":"#/components/schemas/JobResourceSummary"},"type":"array"},"url":{"$ref":"#/components/schemas/RepositoryURLs","description":"URLs contains URLs for the reference branch or commit if applicable."},"warnings":{"items":{"type":"string"},"type":"array"}},"type":"object"}}`)
